"""Headless smoke test of the demo owner page (owner.html) + cars-for-sale.html.  Usage: owner_smoke.py BASE_URL"""
import base64, io, json, sys
from playwright.sync_api import sync_playwright
from PIL import Image, ImageDraw, ImageFilter
BASE = sys.argv[1].rstrip("/") + "/"; OUT = "/workspace/sites/okscars/screenshots/"
AXE = open("/workspace/work/tools/node_modules/axe-core/axe.min.js").read()
res = []
def ok(c, m): res.append(("PASS " if c else "FAIL ") + m)
# test photo: a simple car silhouette on a sky/road gradient (2000x1300, so it must be downscaled)
im = Image.new("RGB", (2000, 1300)); d = ImageDraw.Draw(im)
for y in range(1300): d.line([(0, y), (2000, y)], fill=(90 + y // 12, 130 + y // 20, 190 - y // 14) if y < 820 else (70, 70, 74))
d.rounded_rectangle((360, 520, 1640, 900), 90, fill=(30, 60, 120)); d.polygon([(620, 520), (800, 360), (1240, 360), (1420, 520)], fill=(40, 80, 150))
d.polygon([(680, 515), (830, 395), (1000, 395), (1000, 515)], fill=(180, 210, 235)); d.polygon([(1030, 515), (1030, 395), (1210, 395), (1350, 515)], fill=(180, 210, 235))
for cx in (640, 1360): d.ellipse((cx - 130, 780, cx + 130, 1040), fill=(20, 20, 20)); d.ellipse((cx - 60, 850, cx + 60, 970), fill=(170, 170, 175))
im = im.filter(ImageFilter.GaussianBlur(1.2)); im.save(OUT + "owner-test-photo.jpg", quality=90)
def axe(pg, tag):
    pg.add_script_tag(content=AXE)
    v = pg.evaluate("async()=>{const r=await axe.run(document,{runOnly:['wcag2a','wcag2aa','wcag21a','wcag21aa','best-practice']});return r.violations.map(v=>v.id+': '+v.nodes.map(n=>n.target.join(' ')).slice(0,3).join(' | '))}")
    ok(not v, f"axe 0 violations ({tag}) {v}")
CLS = "window.__cls=0;new PerformanceObserver(l=>{for(const e of l.getEntries()) if(!e.hadRecentInput) window.__cls+=e.value}).observe({type:'layout-shift',buffered:true})"
with sync_playwright() as p:
    b = p.chromium.launch(executable_path="/usr/bin/google-chrome")
    for vw in (1440, 390):
        ctx = b.new_context(viewport={"width": vw, "height": 900}); ctx.add_init_script(CLS); pg = ctx.new_page()
        errs = []; pg.on("pageerror", lambda e: errs.append(str(e))); pg.on("console", lambda m: m.type == "error" and errs.append(m.text))
        pg.on("dialog", lambda dlg: dlg.accept())
        pg.goto(BASE + "cars-for-sale.html", wait_until="networkidle"); pg.wait_for_timeout(800)
        ok(pg.evaluate("window.__cls") == 0, f"[{vw}] cars-for-sale CLS 0 with no local data ({pg.evaluate('window.__cls')})")
        n_seed = pg.locator("[data-listings] .listing").count()
        pg.goto(BASE + "owner.html", wait_until="networkidle"); pg.wait_for_timeout(600)
        ok(pg.locator(".owner-note").inner_text().find("saved only in this browser") > 0, f"[{vw}] demo-mode note visible")
        ok(pg.locator(".owner-car").count() == n_seed, f"[{vw}] owner list shows the {n_seed} seed cars")
        # validation
        pg.click("button[type=submit]"); pg.wait_for_timeout(200)
        ok(pg.locator('[aria-invalid="true"]').count() == 4, f"[{vw}] empty submit flags year, make, model, photo")
        pg.set_input_files("#o-photo", {"name": "notes.txt", "mimeType": "text/plain", "buffer": b"hello"}); pg.fill("#o-year", "2022"); pg.fill("#o-make", "Toyota"); pg.fill("#o-model", "Raize 1.0 Turbo CVT")
        pg.click("button[type=submit]"); pg.wait_for_timeout(200)
        ok("JPG, PNG or WebP" in pg.locator("#o-photo-err").inner_text(), f"[{vw}] non-image file rejected")
        # add
        pg.set_input_files("#o-photo", OUT + "owner-test-photo.jpg"); pg.select_option("#o-status", "Reserved"); pg.click("button[type=submit]")
        pg.wait_for_selector("[data-preview]:not([hidden])", timeout=15000); pg.wait_for_timeout(300)
        src = pg.get_attribute("[data-preview]", "src"); raw = base64.b64decode(src.split(",", 1)[1]); post = Image.open(io.BytesIO(raw))
        ok(post.size == (1080, 1080) and post.format == "JPEG" and len(raw) <= 200 * 1024, f"[{vw}] post is 1080x1080 JPEG, {len(raw) // 1024} KB (<= 200 KB)")
        if vw == 1440: open(OUT + "owner-sample.jpg", "wb").write(raw)
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')")); car = [c for c in st["over"].values() if c["model"].startswith("Raize")][0]
        up = base64.b64decode(car["upload"].split(",", 1)[1]); upi = Image.open(io.BytesIO(up))
        ok(max(upi.size) == 1080 and len(up) <= 150 * 1024 and "image" not in car and "source" not in car, f"[{vw}] stored photo {upi.size}, {len(up) // 1024} KB; no post image stored")
        ok(car["status"] == "Reserved", f"[{vw}] status saved")
        ok(pg.locator("[data-download]").is_visible(), f"[{vw}] Download post image button shown")
        with pg.expect_download() as dl: pg.click("[data-download]")
        ok(dl.value.suggested_filename == "okscars-2022-toyota-raize-1-0-turbo-cvt.jpg", f"[{vw}] download works ({dl.value.suggested_filename})")
        card = pg.locator(".owner-car", has_text="Raize"); ok(card.locator(".car-card__stamp").inner_text().strip().lower().endswith("reserved"), f"[{vw}] owner card shows Reserved stamp")
        if vw == 1440: axe(pg, "owner.html with a local car")
        # cars-for-sale shows it
        pg.goto(BASE + "cars-for-sale.html", wait_until="networkidle"); pg.wait_for_timeout(800)
        art = pg.locator("[data-listings] .listing", has_text="2022 Toyota Raize")
        ok(art.count() == 1 and art.locator(".car-card__photo").get_attribute("src").startswith("data:image/jpeg"), f"[{vw}] new car on cars-for-sale with its stored photo as the card image")
        ok(art.locator(".car-card__stamp").count() == 1 and art.locator(".car-card__phone").inner_text() == "+63 945 774 3386", f"[{vw}] card overlay: stamp + phone + logo as HTML")
        ok(pg.locator("[data-listings] .listing").count() == n_seed + 1, f"[{vw}] seed + 1 local = {n_seed + 1} cards")
        ok(pg.locator("[data-listings] .car-card__stamp").count() == 1, f"[{vw}] blank-status seed cars have no stamp")
        pg.click('.chip[data-value="SUV"]'); pg.wait_for_timeout(200); vis = pg.locator("[data-listings] .listing:not([hidden])").count()
        ok(vis == 1, f"[{vw}] filters still work after re-render (SUV -> {vis})"); pg.click('.chip[data-filter="body"][data-value="all"]')
        if vw == 1440: pg.wait_for_timeout(1800); axe(pg, "cars-for-sale.html with a local car")
        # edit: change status + model, no new photo -> post regenerated
        pg.goto(BASE + "owner.html", wait_until="networkidle"); pg.wait_for_timeout(600)
        pg.locator(".owner-car", has_text="Raize").locator("[data-edit]").click(); pg.wait_for_selector("[data-preview]:not([hidden])"); pg.wait_for_timeout(400)
        ok(pg.input_value("#o-model") == "Raize 1.0 Turbo CVT" and pg.input_value("#o-status") == "Reserved", f"[{vw}] edit loads the car into the form")
        before = pg.get_attribute("[data-preview]", "src")
        pg.fill("#o-model", "Raize 1.2 E CVT"); pg.select_option("#o-status", "Sold"); pg.click("button[type=submit]")
        pg.wait_for_function("s=>document.querySelector('[data-preview]').src!==s", arg=before, timeout=15000); pg.wait_for_timeout(300)
        raw2 = base64.b64decode(pg.get_attribute("[data-preview]", "src").split(",", 1)[1])
        ok(Image.open(io.BytesIO(raw2)).size == (1080, 1080) and len(raw2) <= 200 * 1024, f"[{vw}] edited post regenerated, {len(raw2) // 1024} KB")
        ok(pg.locator(".owner-car", has_text="Raize 1.2 E CVT").locator(".car-card__stamp").inner_text().strip().lower().endswith("sold"), f"[{vw}] list shows edited car as Sold")
        # blank status: no stamp on card
        pg.locator(".owner-car", has_text="Raize").locator("[data-edit]").click(); pg.wait_for_timeout(300); pg.select_option("#o-status", ""); pg.click("button[type=submit]"); pg.wait_for_timeout(1500)
        ok(pg.locator(".owner-car", has_text="Raize").locator(".car-card__stamp").count() == 0, f"[{vw}] status None -> no stamp")
        # edit a seed car (uses its public photo; nothing uploaded)
        pg.locator(".owner-car", has_text="Vios").locator("[data-edit]").click(); pg.wait_for_timeout(300); pg.select_option("#o-status", "Reserved"); pg.click("button[type=submit]"); pg.wait_for_timeout(1500)
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')"))
        ok(st["over"]["vios"]["status"] == "Reserved" and "upload" not in st["over"]["vios"], f"[{vw}] seed edit stored as override without a photo copy")
        # delete local + seed (tombstone)
        pg.locator(".owner-car", has_text="Raize").locator("[data-delete]").click(); pg.wait_for_timeout(300)
        pg.locator(".owner-car", has_text="Wigo").locator("[data-delete]").click(); pg.wait_for_timeout(300)
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')"))
        ok(not any(k.startswith("local-") for k in st["over"]) and st["tomb"] == ["wigo"], f"[{vw}] deleted local car; seed Wigo tombstoned")
        pg.goto(BASE + "cars-for-sale.html", wait_until="networkidle"); pg.wait_for_timeout(800)
        txt = pg.locator("[data-listings]").inner_text()
        ok("Raize" not in txt and "Wigo" not in txt and pg.locator("[data-listings] .listing", has_text="Vios").locator(".car-card__stamp").count() == 1, f"[{vw}] cars-for-sale reflects deletes + seed edit")
        pg.goto(BASE + "owner.html", wait_until="networkidle"); pg.wait_for_timeout(500); pg.click("[data-reset]"); pg.wait_for_timeout(400)
        ok(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')") is None and pg.locator(".owner-car").count() == n_seed, f"[{vw}] Reset demo data restores the {n_seed} seed cars")
        # ---- new fields: condition default, body/trans/fuel/features, spec line, filters, seed overrides-only ----
        ok(pg.input_value("#o-condition") == "Second-hand", f"[{vw}] Condition defaults to Second-hand")
        pg.fill("#o-year", "2024"); pg.fill("#o-make", "Mitsubishi"); pg.fill("#o-model", "Montero Sport GT"); pg.select_option("#o-condition", "Brand-new")
        pg.select_option("#o-body", "SUV"); pg.select_option("#o-trans", "Manual"); pg.select_option("#o-fuel", "Diesel"); pg.fill("#o-features", " Dashcam ,  Push start,, ")
        pg.set_input_files("#o-photo", OUT + "owner-test-photo.jpg"); pg.click("button[type=submit]"); pg.wait_for_selector(".owner-car:has-text('Montero')", timeout=15000); pg.wait_for_timeout(800)
        ok(pg.input_value("#o-condition") == "Second-hand" and pg.input_value("#o-body") == "" and pg.input_value("#o-features") == "", f"[{vw}] form resets to Second-hand after save")
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')")); m = [c for c in st["over"].values() if c["model"] == "Montero Sport GT"][0]
        ok(m["condition"] == "Brand-new" and m["body"] == "SUV" and m["trans"] == "Manual" and m["fuel"] == "Diesel" and m["features"] == ["Dashcam", "Push start"], f"[{vw}] new fields saved (features as array {m['features']})")
        oc = pg.locator(".owner-car", has_text="Montero").locator(".listing__specs li").all_inner_texts()
        ok(oc == ["Brand-new", "SUV", "Manual", "Diesel", "Dashcam", "Push start"], f"[{vw}] owner card spec line {oc}")
        # prefill when editing a seed car, and save only overrides
        pg.locator(".owner-car", has_text="Almera").locator("[data-edit]").click(); pg.wait_for_timeout(400)
        pre = [pg.input_value(f"#o-{k}") for k in ("condition", "body", "trans", "fuel", "features")]
        ok(pre == ["Second-hand", "Sedan", "Automatic", "Gasoline", "360° camera"], f"[{vw}] seed car prefilled {pre}")
        pg.fill("#o-features", "360° camera, Leather seats"); pg.click("button[type=submit]"); pg.wait_for_timeout(1800)
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')")); al = st["over"].get("almera", {})
        ok(sorted(al) == ["features", "id", "updated"] and al["features"] == ["360° camera", "Leather seats"], f"[{vw}] seed edit stores only overrides {sorted(al)}")
        pg.locator(".owner-car", has_text="Almera").locator("[data-edit]").click(); pg.wait_for_timeout(300); pg.fill("#o-features", "360° camera"); pg.click("button[type=submit]"); pg.wait_for_timeout(1800)
        st = json.loads(pg.evaluate("localStorage.getItem('okscars-demo-cars-v1')"))
        ok("almera" not in st["over"], f"[{vw}] editing back to the seed values removes the override")
        pg.locator(".owner-car", has_text="Montero").locator("[data-edit]").click(); pg.wait_for_timeout(300)
        ok(pg.input_value("#o-condition") == "Brand-new", f"[{vw}] editing keeps the saved Brand-new condition")
        pg.click("[data-cancel-edit]"); ok(pg.input_value("#o-condition") == "Second-hand", f"[{vw}] cancel resets Condition to Second-hand")
        # cars-for-sale: no pills, spec line, filters include the owner car
        pg.goto(BASE + "cars-for-sale.html", wait_until="networkidle"); pg.wait_for_timeout(900)
        ok(pg.locator("[data-listings] .chip-static, [data-listings] .listing__meta").count() == 0, f"[{vw}] no condition/body pills on cars-for-sale")
        mt = pg.locator("[data-listings] .listing", has_text="Montero").locator(".listing__specs li").all_inner_texts()
        ok(mt == ["Brand-new", "SUV", "Manual", "Diesel", "Dashcam", "Push start"], f"[{vw}] cars-for-sale spec line {mt}")
        alm = pg.locator("[data-listings] .listing", has_text="Almera").locator(".listing__specs li").all_inner_texts()
        ok(alm == ["Second-hand", "Sedan", "Automatic", "Gasoline", "360° camera"], f"[{vw}] seed spec line {alm}")
        def shown(): return sorted(pg.locator("[data-listings] .listing:not([hidden]) .car-card__title").all_inner_texts())
        pg.click('.chip[data-value="SUV"]'); pg.wait_for_timeout(250); suv = shown()
        ok(len(suv) == 2 and any("MONTERO" in t.upper() for t in suv), f"[{vw}] SUV filter includes the owner car {suv}")
        pg.click('.chip[data-value="Brand-new"]'); pg.wait_for_timeout(250); bn = shown()
        ok(len(bn) == 1 and "MONTERO" in bn[0].upper(), f"[{vw}] Brand-new + SUV -> only the owner car {bn}")
        pg.click('.chip[data-filter="body"][data-value="all"]'); pg.wait_for_timeout(250); bn2 = shown()
        ok(len(bn2) == 2, f"[{vw}] Brand-new (all types) -> Wigo + owner car {bn2}")
        pg.click('.chip[data-filter="condition"][data-value="all"]'); pg.wait_for_timeout(250)
        ok(len(shown()) == n_seed + 1, f"[{vw}] All -> {n_seed + 1} cards")
        pg.goto(BASE + "index.html", wait_until="networkidle")
        ok(pg.locator(".chip-static").count() == 0 and pg.locator(".listing .listing__specs").count() == 3, f"[{vw}] home cards: no pills, spec line")
        pg.goto(BASE + "owner.html", wait_until="networkidle"); pg.wait_for_timeout(500); pg.click("[data-reset]"); pg.wait_for_timeout(300)
        ok(not errs, f"[{vw}] no console/page errors {errs[:2]}")
        ctx.close()
    # no-JS fallback
    ctx = b.new_context(java_script_enabled=False); pg = ctx.new_page(); pg.goto(BASE + "cars-for-sale.html")
    ok(pg.locator("[data-listings] .listing").count() == 6, "no-JS: 6 server-rendered seed cards"); ctx.close()
    b.close()
print("\n".join(res)); print(f"\n{sum(r.startswith('PASS') for r in res)} passed, {sum(r.startswith('FAIL') for r in res)} failed")
